import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M3.5 8a2.5 2.5 0 1 1 .608-4.926 4.002 4.002 0 0 1 7.382-1.03A3 3 0 1 1 12 8zM3 10a1 1 0 0 1 2 0v4a1 1 0 1 1-2 0zm7-1a1 1 0 0 0-1 1v5a1 1 0 1 0 2 0v-5a1 1 0 0 0-1-1m2 1a1 1 0 1 1 2 0v2a1 1 0 1 1-2 0zM7 9a1 1 0 0 0-1 1v2a1 1 0 1 0 2 0v-2a1 1 0 0 0-1-1"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M4 10a3 3 0 1 1 1.065-5.806A5.001 5.001 0 0 1 14.63 3.11q.418-.108.87-.109a3.5 3.5 0 1 1 0 7zm0 2a1 1 0 0 1 1 1v5a1 1 0 1 1-2 0v-5a1 1 0 0 1 1-1m9 1a1 1 0 1 0-2 0v6a1 1 0 1 0 2 0zm3-1a1 1 0 0 1 1 1v3a1 1 0 1 1-2 0v-3a1 1 0 0 1 1-1m-7 1a1 1 0 1 0-2 0v3a1 1 0 1 0 2 0z"] as readonly string[];

export const RainIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="rain" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
RainIcon.displayName = `Blueprint6.Icon.RainIcon`;

/**
 * @deprecated Use {@link RainIcon} instead.
 */
export const Rain: typeof RainIcon = RainIcon;

export default RainIcon;
